# bracket: generated by ShapeBridge (https://github.com/gazi-faysal-jubayer/shapebridge)
# Units: mm. Edit the parameters below; geometry updates from them.

import math
import cadquery as cq

# sketch planes: (x direction, normal); the normal is x × y
FRAMES = {"XY": ((1, 0, 0), (0, 0, 1)), "XZ": ((1, 0, 0), (0, -1, 0)), "YZ": ((0, 1, 0), (1, 0, 0))}


def plane(base, offset):
    x, n = FRAMES[base]
    return cq.Workplane(cq.Plane(origin=tuple(c * offset for c in n), xDir=x, normal=n))


def build(width=80, depth=40, thickness=8, boss_r=12, corner_r=4):
    boss_h = thickness * 2
    hole_d = boss_r
    # base
    def tool_base():
        return plane("XY", 0).polyline([(0, 0), (width, 0), (width, depth), (0, depth)]).close().extrude(thickness)
    result = tool_base()
    # corners
    result = result.edges("|Z").fillet(corner_r)
    # boss
    def tool_boss():
        return plane("XY", thickness).moveTo(width / 2, depth / 2).circle(boss_r).extrude(boss_h)
    result = result.union(tool_boss())
    # bore
    def tool_bore():
        solids = []
        top = cq.Vector(width / 2, depth / 2, thickness + boss_h) + cq.Vector((0, 0, 1)) * 0.0001
        solids.append(cq.Solid.makeCylinder(hole_d / 2, thickness + boss_h + 0.0001, top, cq.Vector((0, 0, -1))))
        return cq.Workplane().add(cq.Compound.makeCompound(solids))
    result = result.cut(tool_bore())
    # mount
    def tool_mount():
        solids = []
        top = cq.Vector(thickness * 1.5, depth / 2, thickness) + cq.Vector((0, 0, 1)) * 0.0001
        solids.append(cq.Solid.makeCylinder(6.6 / 2, thickness + 0.0001, top, cq.Vector((0, 0, -1))))
        solids.append(cq.Solid.makeCylinder(11 / 2, 3 + 0.0001, top, cq.Vector((0, 0, -1))))
        top = cq.Vector(width - thickness * 1.5, depth / 2, thickness) + cq.Vector((0, 0, 1)) * 0.0001
        solids.append(cq.Solid.makeCylinder(6.6 / 2, thickness + 0.0001, top, cq.Vector((0, 0, -1))))
        solids.append(cq.Solid.makeCylinder(11 / 2, 3 + 0.0001, top, cq.Vector((0, 0, -1))))
        return cq.Workplane().add(cq.Compound.makeCompound(solids))
    result = result.cut(tool_mount())
    return result


result = build()
if "show_object" in globals():
    show_object(result)
elif __name__ == "__main__":
    cq.exporters.export(result, "bracket.step")
